import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"用 Dougong 开发自己的 SaaS","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/docs/","contentType":"overview","prev":false,"next":{"text":"创建自己的项目","link":"/getting-started/create-project"}},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),n={name:"docs/index.md"};function o(d,a,i,c,l,p){return t(),r("div",null,[...a[0]||(a[0]=[s(`<h1 id="用-dougong-开发自己的-saas" tabindex="-1">用 Dougong 开发自己的 SaaS <a class="header-anchor" href="#用-dougong-开发自己的-saas" aria-label="Permalink to &quot;用 Dougong 开发自己的 SaaS&quot;">​</a></h1><p>从 Rust + Axum 后端开始，实现自己的业务模块，接入身份、数据库、审计、文件与后台任务，再交付能够验证和部署的 API。</p><div class="docs-paths"><a class="docs-path" href="../learn/"><strong>从头开发一个业务</strong><span>开发工单 SaaS 后端，逐步接入数据、权限、文件与后台任务。</span></a><a class="docs-path" href="../architecture/project-structure"><strong>已有后端经验</strong><span>先了解代码归属，再按数据库、接口、用例与测试进入开发指南。</span></a><a class="docs-path" href="../reference/api"><strong>正在使用框架</strong><span>查阅公共 API、配置、模块接入和运行命令。</span></a></div><h2 id="框架提供什么-你负责什么" tabindex="-1">框架提供什么，你负责什么 <a class="header-anchor" href="#框架提供什么-你负责什么" aria-label="Permalink to &quot;框架提供什么，你负责什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>框架能力</th><th>自己的业务负责</th></tr></thead><tbody><tr><td>身份、Session、成员与企业角色</td><td>实体、业务规则与资源访问范围</td></tr><tr><td>配置、连接池、迁移入口、统一错误</td><td>用例、业务事务与 HTTP 合同</td></tr><tr><td>审计、幂等、文件、任务、通知和邮件</td><td>操作的审计语义、文件归属和任务 Handler</td></tr><tr><td>OpenAPI、生成 SDK、测试与部署入口</td><td>业务接口的验证、生产配置和运行维护</td></tr></tbody></table><p>当前每次部署服务一家 Organization。企业内部可以有多个成员和业务资源；多家客户企业共享一份部署需要重新设计企业上下文与访问合同，见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">部署范围决策</a>。</p><h2 id="从一条业务请求建立心智模型" tabindex="-1">从一条业务请求建立心智模型 <a class="header-anchor" href="#从一条业务请求建立心智模型" aria-label="Permalink to &quot;从一条业务请求建立心智模型&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP / 请求 DTO</span></span>
<span class="line"><span>  → 自己的业务用例</span></span>
<span class="line"><span>  → Core 公共接口与事务</span></span>
<span class="line"><span>  → PostgreSQL / Platform 适配器</span></span>
<span class="line"><span>  → 响应 DTO / OpenAPI</span></span></code></pre></div><p>应用入口组合 Router 与 OpenAPI；模块拥有规则和表；Core 提供可复用 SaaS 能力；Platform 封装基础设施。具体位置见<a href="./../architecture/project-structure">项目结构</a>，边界见<a href="./../architecture/boundaries">Core 与业务模块</a>。</p><h2 id="先运行-再开发" tabindex="-1">先运行，再开发 <a class="header-anchor" href="#先运行-再开发" aria-label="Permalink to &quot;先运行，再开发&quot;">​</a></h2><p>按<a href="./../getting-started/quickstart">快速开始</a>准备工具，再进入<a href="./../learn/">工单 SaaS 课程</a>，在独立副本中逐步实现 <code>tickets</code> 模块。四个检查点可以运行完整代码，十课围绕同一业务学习数据库、协议、授权、事务、文件、任务、验证与部署。<a href="./../guides/new-module">新增业务模块</a>提供简明接入指南。</p><p>每份指南提供要修改的位置、公开接口、最小代码、可观察结果和失败边界。生成的 <a href="./../reference/api">API</a>与<a href="./../reference/config">配置</a>保持实现为唯一事实来源。</p><h2 id="查阅完整参考实现" tabindex="-1">查阅完整参考实现 <a class="header-anchor" href="#查阅完整参考实现" aria-label="Permalink to &quot;查阅完整参考实现&quot;">​</a></h2><p>内置知识库串联了业务 CRUD、资源授权、附件、导出、通知与审计。读它的实现来理解怎样组合 Core，再将领域规则替换为自己的业务。可以从<a href="./../tutorials/personal-documents">文档用例</a>、<a href="./../tutorials/library-grants">资源权限</a>和<a href="./../tutorials/document-exports">任务导出</a>查阅一条完整链路。</p><h2 id="客户端与贡献" tabindex="-1">客户端与贡献 <a class="header-anchor" href="#客户端与贡献" aria-label="Permalink to &quot;客户端与贡献&quot;">​</a></h2><p>后端合同完成后，按<a href="./../tutorials/electron-shell">客户端共享</a>与<a href="./../tutorials/add-example">业务贡献</a>接入 Web 和 Electron。文档提供中文与英文，同页语言切换保留章节，搜索只覆盖公开文档。</p><p>修改文档时阅读<a href="./../guides/documentation">作者规范</a>，发布自己的站点见<a href="./../getting-started/publish-docs">发布指南</a>。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/getting-started/documentation.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,19)])])}const b=e(n,[["render",o]]);export{u as __pageData,b as default};
